import argparse
import datetime
import json
import sys
from typing import List

from kitty import ledger, reports, store
from kitty.errors import KittyError
from kitty.store import STATE_FILE


class KittyParser(argparse.ArgumentParser):
    def error(self, message):
        raise KittyError(message)


def _parser() -> KittyParser:
    p = KittyParser(prog="kitty", allow_abbrev=False)
    top = p.add_subparsers(dest="command", required=True)

    def add(sub, name):
        return sub.add_parser(name, allow_abbrev=False)

    c = add(top, "init")
    c.add_argument("currency")

    m = add(top, "member")
    msub = m.add_subparsers(dest="action", required=True)
    for name in ("add", "remove"):
        add(msub, name).add_argument("name")
    add(msub, "list")

    e = add(top, "expense")
    esub = e.add_subparsers(dest="action", required=True)
    ea = add(esub, "add")
    ea.add_argument("payer")
    ea.add_argument("amount")
    ea.add_argument("description", nargs="+")
    for opt in ("among", "exact", "shares", "percent", "currency", "date", "category"):
        ea.add_argument("--" + opt)
    add(esub, "list")
    add(esub, "remove").add_argument("id")

    pay = add(top, "payment")
    psub = pay.add_subparsers(dest="action", required=True)
    pa = add(psub, "add")
    for a in ("sender", "receiver", "amount"):
        pa.add_argument(a)
    pa.add_argument("--currency")
    pa.add_argument("--date")

    r = add(top, "rate")
    rsub = r.add_subparsers(dest="action", required=True)
    rs = add(rsub, "set")
    rs.add_argument("currency")
    rs.add_argument("rate")

    add(top, "balances")
    add(top, "settle")
    add(top, "history").add_argument("name")
    add(top, "report")
    add(top, "export").add_argument("file")
    return p


def _today() -> str:
    return datetime.date.today().isoformat()


def _run(args) -> None:
    cmd = args.command
    if cmd == "init":
        store.init(STATE_FILE, args.currency)
        return
    state = store.load(STATE_FILE)
    out = None
    write = False
    if cmd == "member":
        if args.action == "add":
            ledger.add_member(state, args.name)
            write = True
        elif args.action == "remove":
            ledger.remove_member(state, args.name)
            write = True
        else:
            out = ledger.list_members(state)
    elif cmd == "expense":
        if args.action == "add":
            new_id = ledger.add_expense(
                state, args.payer, args.amount, " ".join(args.description),
                date=args.date if args.date is not None else _today(),
                among=args.among, exact=args.exact, shares=args.shares,
                percent=args.percent, currency=args.currency, category=args.category)
            write = True
            print_after = str(new_id)
        elif args.action == "remove":
            ledger.remove_expense(state, args.id)
            write = True
        else:
            out = ledger.list_expenses(state)
    elif cmd == "payment":
        ledger.add_payment(state, args.sender, args.receiver, args.amount,
                           date=args.date if args.date is not None else _today(),
                           currency=args.currency)
        write = True
    elif cmd == "rate":
        ledger.set_rate(state, args.currency, args.rate)
        write = True
    elif cmd == "balances":
        out = reports.balances(state)
    elif cmd == "settle":
        out = reports.settle(state)
    elif cmd == "history":
        out = reports.history(state, args.name)
    elif cmd == "report":
        out = reports.category_report(state)
    elif cmd == "export":
        reports.export_csv(state, args.file)
    if write:
        store.save(STATE_FILE, state)
        if cmd == "expense" and args.action == "add":
            print(print_after)
    if out is not None:
        print(json.dumps(out, ensure_ascii=False))


def main(argv: List[str]) -> int:
    try:
        args = _parser().parse_args(argv)
        _run(args)
    except KittyError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1
    return 0
